<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Service\Visibility\TemplateVariableRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAccesible
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(TemplateVariableRestrictFilterToVisibility $event): TemplateVariableRestrictFilterToVisibility
    {
        $this->logDebug("Check TenantAccesible Template variable");
        $span = $this->startSpan("Check TenantAccesible Template variable");
        try {
            $userContext = $this->context->getIdentity();
            if (!$userContext->hasAnyRole('platform:*')) {
                $tenantTenantAccesible = $userContext->tenant;
                if (!$userContext->anonymous && null !== $tenantTenantAccesible) {
                    $event->templateVariableFilter = $event->templateVariableFilter->withTenantTenantAccesible($tenantTenantAccesible);
                } else {
                    throw new UnauthorizedException('The claim tenant is required');
                }
            }
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
